import {DEMO_AIRCRAFT_LABEL} from './booking-view.js';
import {AEROPORTOS,PREMISSAS,COTISTAS,MESES,simular,financeiro,ratearCentavos,formatarHoras,hojeISO,isoLocal,parseData,deslocarData,dataBloqueada,validarReserva,lerReservas,reservasIniciais,STORAGE_KEY} from './model.js';
const $=s=>document.querySelector(s);
const money=(n,d=2)=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:d,maximumFractionDigits:d});
const num=(n,d=0)=>n.toLocaleString('pt-BR',{maximumFractionDigits:d,minimumFractionDigits:d});
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=iso=>parseData(iso).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error();},removeItem:()=>{}};}
let reservas=lerReservas(storage),tab='resumo',mesFinanceiro=5,cotista='todos',categoria='TODAS',financeView='balanco',chartMetric='custos',unit='km',fact=0;
let month=new Date();month.setDate(1);month.setHours(12,0,0,0);
const primeiroDia=(()=>{let data=deslocarData(hojeISO(),1);while(dataBloqueada(data,reservas))data=deslocarData(data,1);return data;})();
let draft={origem:'SBCY',destino:'SBSI',data:primeiroDia,horario:'09:00',passageiros:4,emprestado:false};
let simDraft={origem:'SBCY',destino:'SBSI',horasAno:120,cotas:3,dias:1,passageiros:4,idaVolta:true};
const content=$('#demo-content'),dialog=$('#detail-dialog');
let toastTimer;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function persist(){try{storage.setItem(STORAGE_KEY,JSON.stringify(reservas));return true;}catch{toast('Seu navegador não permite salvar a demo. As reservas funcionam enquanto esta página estiver aberta.');return false;}}
function modal(html){$('#dialog-content').innerHTML=html;dialog.showModal();}
$('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function options(selected){return AEROPORTOS.map(a=>`<option value="${a.codigo}" ${a.codigo===selected?'selected':''}>${a.codigo} · ${a.nome}</option>`).join('');}
function selectAirport(name,label,value){return `<label class="field">${label}<select name="${name}" aria-label="${label}" required>${options(value)}</select></label>`;}
function heading(title,copy,badge='DADOS FICTÍCIOS'){return `<div class="portal-heading"><div><h3>${title}</h3><p>${copy}</p></div><span class="badge">${badge}</span></div>`;}
function stat(label,value,copy,extra=''){return `<div class="stat-card ${extra}"><span class="stat-label">${label}</span><strong class="stat-number">${value}</strong><p>${copy}</p></div>`;}
function nextFlight(){return reservas.filter(v=>v.status!=='CANCELADO'&&v.data>=hojeISO()).sort((a,b)=>a.data.localeCompare(b.data)||a.horario.localeCompare(b.horario))[0];}
function animateScreen(el){if(!el||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:420,easing:'cubic-bezier(.2,.7,.2,1)'});}
function goTab(value,focus=false){tab=value;document.querySelectorAll('#portal-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});render();animateScreen(content);if(focus)content.focus({preventScroll:true});}
function render(){({resumo:renderResumo,agenda:renderAgenda,simulador:renderSimulador,financeiro:renderFinanceiro,manutencao:renderManutencao}[tab]||renderResumo)();}
function renderResumo(){const f=financeiro(5),n=nextFlight();
 content.innerHTML=`<div class="portal-welcome"><img src="assets/hero-aircraft.jpg" alt="" loading="lazy"><p class="eyebrow">BEM-VINDO À SUA EXPERIÊNCIA</p><h3>Olá, Cliente Share.</h3><p>DEMO-01 <strong>· Turboélice executivo</strong><br>3 cotistas · participações iguais · cenário fictício</p></div>
 <div class="stat-grid">${stat('SEU TEMPO EM VOO',formatarHoras(f.saldos[0].horas),'Novembro de 2026 · histórico fictício')}${stat('DISTÂNCIA PERCORRIDA',unit==='km'?`4.800 <small>km</small>`:`2.592 <small>NM</small>`,`<span class="distance-options"><button data-action="unit" data-value="km" aria-pressed="${unit==='km'}">km</button><button data-action="unit" data-value="nm" aria-pressed="${unit==='nm'}">milhas náuticas</button></span>`)}${stat('SUA PARTICIPAÇÃO NAS DESPESAS',money(f.saldos[0].devido/100,0),'Novembro · veja o rateio no financeiro','gold')}</div>
 <div class="portal-two"><div class="panel"><div class="panel-title"><h4>Seu próximo voo</h4><span class="badge ${n?.status==='CONFIRMADO'?'success':'warning'}">${n?n.status:'SEM RESERVA'}</span></div>${n?`<div class="route-line"><strong>${esc(n.origem)}</strong><span aria-hidden="true">✈</span><strong>${esc(n.destino)}</strong></div><p class="dim">${fmtDate(n.data)} · ${esc(n.horario)} · ${Number(n.passageiros)} passageiros</p><p class="dim" style="margin-top:7px">${esc(n.id)} · ${n.status==='CONFIRMADO'?'Tripulação demonstrativa definida':'Aguarda a confirmação simulada'}</p>`:'<p class="dim">Escolha um destino e experimente solicitar uma viagem.</p>'}<div class="mini-actions"><button class="mini-button accent" data-open="agenda">Agendar um voo <span class="arrow-ne" aria-hidden="true"></span></button></div></div><div class="panel"><div class="panel-title"><h4>Transparência em cada voo</h4><span class="badge">NO SEU TEMPO</span></div><p class="dim">Antes de viajar, entenda o custo. Depois, acompanhe cada lançamento e sua parte no rateio.</p><div class="mini-actions"><button class="mini-button" data-open="simulador">Simular uma viagem <span class="arrow-ne" aria-hidden="true"></span></button><button class="mini-button" data-open="financeiro">Ver meu balanço <span class="arrow-ne" aria-hidden="true"></span></button></div></div></div>
 <div class="fact-row"><span>${['Seu destino mais visitado no cenário é Sinop: 4 pousos em novembro.','Os 4.800 km do cenário equivalem a cerca de 12% da circunferência da Terra.','Os indicadores de horas e custos mudam ao selecionar outro mês no financeiro.'][fact%3]}</span><button data-action="fact">Outra curiosidade ↻</button></div><div class="demo-hint">Comece pelo agendamento ou simule sua próxima viagem. O voo que você criar aparecerá neste resumo; os históricos financeiros são cenários fictícios independentes.</div>`;
}
function renderAgenda(){content.innerHTML=heading('Agendamento de voo','Solicite um voo, acompanhe o status e consulte seu diário de bordo.')+`
 <div class="booking-tabs" role="group" aria-label="Agendamento"><button class="active" data-action="booking-view" data-value="agendar" aria-pressed="true">Agendar</button><button data-action="booking-view" data-value="historico" aria-pressed="false">Histórico</button><button data-open="simulador">Simular</button></div>
 <div id="booking-new"><form id="booking-form" class="real-booking"><div class="booking-fields"><div class="booking-airports">${selectAirport('origem','Saindo de',draft.origem)}${selectAirport('destino','Indo para',draft.destino)}<button type="button" class="booking-swap" data-action="swap-airports" aria-label="Inverter origem e destino">⇄</button></div><div class="booking-date-title"><span>DATA DO VOO</span><span><i></i> Ocupado <i class="selected-dot"></i> Selecionado</span></div><div id="calendar"></div><label class="field booking-date-input">Data de saída<input name="data" type="date" value="${draft.data}" min="${deslocarData(hojeISO(),1)}" max="${maxDate()}" required></label><div class="booking-options"><label class="field">Horário previsto · Brasília<input name="horario" type="time" value="${draft.horario}" required></label><label class="field">Passageiros<select name="passageiros">${[1,2,3,4,5,6].map(i=>`<option ${i===Number(draft.passageiros)?'selected':''}>${i}</option>`).join('')}</select></label></div><label class="field">Observações<textarea name="observacoes" rows="3" maxlength="800" placeholder="Escalas, preferências, bagagem…">${esc(draft.observacoes||'')}</textarea></label><label class="check"><input name="emprestado" type="checkbox" ${draft.emprestado?'checked':''}> Solicitar uso de horas de outro cotista</label><p id="booking-error" class="form-error" role="alert" hidden></p></div>
 <aside class="booking-summary"><div class="booking-cover"><img src="assets/hero-aircraft.jpg" alt="Aeronave ilustrativa" loading="lazy"><div class="booking-route"><strong id="booking-origin">${esc(draft.origem)}</strong><span aria-hidden="true">✈</span><strong id="booking-destination">${esc(draft.destino)}</strong></div></div><div class="booking-summary-body"><p class="eyebrow">RESUMO DA SOLICITAÇÃO</p><dl><div><dt>Aeronave</dt><dd>${DEMO_AIRCRAFT_LABEL}</dd></div><div><dt>Período</dt><dd id="booking-period">${fmtDate(draft.data)}</dd></div><div><dt>Horário</dt><dd id="booking-time">${esc(draft.horario)}</dd></div><div><dt>Duração</dt><dd>1 dia</dd></div><div><dt>Passageiros</dt><dd id="booking-passengers">${Number(draft.passageiros)}</dd></div></dl><button type="submit" class="booking-submit">Solicitar voo <span aria-hidden="true">→</span></button><p class="dim">A solicitação fica pendente até a confirmação da coordenação de voo da Share Brasil.</p></div></aside></form></div><section id="booking-history" class="booking-list" aria-labelledby="booking-list-title" hidden><h4 id="booking-list-title">Seus agendamentos de demonstração</h4>${bookingCards()}</section>`;renderCalendar();}
function updateBookingSummary(){if(!$('#booking-origin'))return;$('#booking-origin').textContent=draft.origem;$('#booking-destination').textContent=draft.destino;$('#booking-period').textContent=draft.data?fmtDate(draft.data):'—';$('#booking-time').textContent=draft.horario;$('#booking-passengers').textContent=draft.passageiros;}
function bookingView(value){const history=value==='historico';$('#booking-new').hidden=history;$('#booking-history').hidden=!history;document.querySelectorAll('[data-action="booking-view"]').forEach(b=>{const active=b.dataset.value===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});animateScreen(history?$('#booking-history'):$('#booking-new'));}
function maxDate(){const d=parseData(hojeISO());d.setMonth(d.getMonth()+6);return isoLocal(d);}
function renderCalendar(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),base=new Date();const baseMonth=base.getFullYear()*12+base.getMonth(),thisMonth=y*12+m;
 $('#calendar').innerHTML=`<div class="calendar-head"><button class="icon-button" data-action="month" data-dir="-1" aria-label="Mês anterior" ${thisMonth<=baseMonth?'disabled':''}>‹</button><strong>${month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="icon-button" data-action="month" data-dir="1" aria-label="Próximo mês" ${thisMonth>=baseMonth+6?'disabled':''}>›</button></div><div class="calendar-grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(d=>`<span class="day-label">${d}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const iso=isoLocal(new Date(y,m,i+1)),past=iso<=hojeISO(),blocked=dataBloqueada(iso,reservas),after=iso>maxDate(),selected=iso===draft.data;return `<button type="button" data-date="${iso}" class="${selected?'selected ':''}${blocked&&!past?'blocked':''}" ${past||blocked||after?'disabled':''} aria-label="${i+1} de ${month.toLocaleDateString('pt-BR',{month:'long'})}${past?', data passada':blocked?', indisponível':''}" aria-pressed="${selected}">${i+1}</button>`;}).join('')}</div><div class="calendar-key"><span><i></i> Disponível</span><span><i></i> Reservado ou manutenção</span></div><p class="dim" style="font-size:9px;margin-top:15px">A disponibilidade é fictícia. As datas com faixa representam reservas e manutenção da demonstração.</p>`;
}
function bookingCards(){return [...reservas].sort((a,b)=>b.data.localeCompare(a.data)).map(v=>`<article class="booking-card"><div><strong>${v.origem} → ${v.destino}</strong><p>${fmtDate(v.data)} · ${v.horario} · ${v.passageiros} passageiros · ${v.id}${v.emprestado?' · horas emprestadas solicitadas':''}</p>${v.status==='CONFIRMADO'?'<p>Comandante Demo e Copiloto Demo · tripulação fictícia</p>':''}<div class="mini-actions">${v.status==='SOLICITADO'?`<button class="mini-button accent" data-action="confirm-booking" data-id="${v.id}">Simular confirmação ✓</button>`:''}${v.status!=='CANCELADO'?`<button class="mini-button" data-action="cancel-booking" data-id="${v.id}">Cancelar reserva</button>`:''}</div></div><span class="badge ${v.status==='CONFIRMADO'?'success':v.status==='SOLICITADO'?'warning':''}">${v.status}</span></article>`).join('')||'<p class="dim">Ainda não há solicitações. Escolha uma data para começar.</p>';}
function captureBooking(form){const d=new FormData(form);draft={origem:d.get('origem'),destino:d.get('destino'),data:d.get('data'),horario:d.get('horario'),passageiros:Number(d.get('passageiros')),emprestado:d.has('emprestado'),observacoes:d.get('observacoes')||''};updateBookingSummary();}
function renderSimulador(){content.innerHTML=heading('O custo, antes do embarque.','Mude a rota e o uso anual para entender as três camadas de custo.','ESTIMATIVA DIDÁTICA')+`
 <div class="sim-layout"><div class="panel"><form id="sim-form" class="portal-form">${selectAirport('origem','Origem',simDraft.origem)}${selectAirport('destino','Destino',simDraft.destino)}<label class="field span-2">Seu uso anual: <strong id="hours-value">${simDraft.horasAno} horas por cotista</strong><input type="range" name="horasAno" min="20" max="400" step="10" value="${simDraft.horasAno}" aria-label="Horas anuais por cotista"><small>Os custos fixos se distribuem pelas suas horas de uso.</small></label><label class="field">Quantidade de cotas<select name="cotas">${[1,2,3,4].map(n=>`<option value="${n}" ${n===Number(simDraft.cotas)?'selected':''}>${n===1?'1 · propriedade integral':n+' cotas iguais'}</option>`).join('')}</select></label><label class="field">Dias de jornada<input type="number" name="dias" min="1" max="7" step="1" value="${simDraft.dias}" required></label><label class="field span-2">Passageiros<select name="passageiros">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===Number(simDraft.passageiros)?'selected':''}>${n} ${n===1?'passageiro':'passageiros'}</option>`).join('')}</select></label><label class="check span-2"><input type="checkbox" name="idaVolta" ${simDraft.idaVolta?'checked':''}> Ida e volta na mesma rota</label><button type="submit" class="mini-button accent span-2">Calcular minha simulação <span class="arrow-ne" aria-hidden="true"></span></button><p id="sim-error" class="form-error span-2" role="alert" hidden></p></form></div><div id="sim-result" aria-live="polite"></div></div><div id="comparison"></div><details class="assumptions"><summary>Entenda as premissas e o que está incluído <span>+</span></summary><ul><li>Turboélice fictício: ${num(PREMISSAS.velocidadeKmh)} km/h, ${PREMISSAS.litrosHora} litros/h e combustível a ${money(PREMISSAS.combustivelLitro)} por litro.</li><li>Tempo estimado em linha reta, acrescido de 9 minutos por trecho. Não é planejamento operacional.</li><li>Curto prazo: combustível + ${money(PREMISSAS.taxaTrecho,0)} de taxa por trecho + ${money(PREMISSAS.diariaPessoa,0)} de diária por tripulante/dia. Dois tripulantes.</li><li>Para cada noite (dias − 1): hotel de ${money(PREMISSAS.hotelPessoa,0)} por tripulante e ${money(PREMISSAS.hangarNoite,0)} de hangaragem. Na ida simples, não há reposicionamento incluído.</li><li>Médio prazo: estrutura anual ilustrativa de ${money(PREMISSAS.fixoAnual,0)} (hangar, tripulação, seguro, manutenção preventiva, gestão e atualizações), dividida igualmente pelas cotas e depois pelas horas anuais de cada cotista.</li><li>Longo prazo: reserva ilustrativa de ${money(PREMISSAS.reservaHora,0)} por hora para revisões futuras.</li><li>Propriedade integral: a mesma pessoa assume toda a estrutura fixa, mantendo o mesmo uso anual e os mesmos variáveis. Táxi aéreo: tarifa hipotética de ${money(PREMISSAS.taxiHora,0)}/h + as mesmas taxas e despesas de estadia. Não são cotações de mercado.</li></ul><p>Não inclui aquisição da aeronave/cota, financiamento, depreciação, tributos específicos, reposicionamentos, desvios meteorológicos ou eventos extraordinários. Estimativa educativa, sem promessa de economia, rentabilidade ou disponibilidade. O plano real depende de análise e contrato.</p></details>`;updateSimulation();}
function captureSim(){const f=$('#sim-form'),d=new FormData(f);simDraft={origem:d.get('origem'),destino:d.get('destino'),horasAno:Number(d.get('horasAno')),cotas:Number(d.get('cotas')),dias:Number(d.get('dias')),passageiros:Number(d.get('passageiros')),idaVolta:d.has('idaVolta')};$('#hours-value').textContent=`${simDraft.horasAno} horas por cotista`;}
function updateSimulation(){try{const s=simular(simDraft);$('#sim-error').hidden=true;
 $('#sim-result').innerHTML=`<div class="sim-result"><p class="eyebrow">${s.origem} → ${s.destino}${s.idaVolta?' → '+s.origem:''}</p><strong class="result-big">${money(s.total)}</strong><p>Custo alocado à viagem · ${formatarHoras(s.horas)} estimadas<br>${num(s.km)} km · ${s.dias} dia(s) · ${s.passageiros} passageiro(s)</p><div class="cost-layers"><div class="cost-layer"><span><i class="layer-dot"></i>Curto prazo<small>Combustível e despesas da viagem</small></span><strong>${money(s.curto)}</strong></div><div class="cost-layer"><span><i class="layer-dot"></i>Médio prazo<small>Sua parcela da estrutura fixa</small></span><strong>${money(s.medio)}</strong></div><div class="cost-layer"><span><i class="layer-dot"></i>Longo prazo<small>Reserva para manutenção futura</small></span><strong>${money(s.longo)}</strong></div></div><p style="font-size:9px;margin-top:8px">Curto prazo é o desembolso estimado da viagem. As outras camadas representam custos fixos alocados e reserva.</p></div>`;
 const max=Math.max(s.total,s.privada,s.taxi);$('#comparison').innerHTML=`<div class="stat-grid" style="margin-top:16px">${stat('CUSTO EFETIVO POR HORA',money(s.custoHora,0),'Viagem + estrutura alocada + reserva')}${stat('CUSTO POR PASSAGEIRO',money(s.porAssento,0),'Total dividido por '+s.passageiros+' · sem venda de assentos')}${stat('SUA ESTRUTURA FIXA MENSAL',money(s.fixoMes,0),num(100/s.cotas,2)+'% dos fixos do cenário')}</div><div class="comparison"><h4>Mesma viagem, três cenários ilustrativos</h4>${[['Compartilhada',s.total],['Propriedade integral',s.privada],['Táxi aéreo hipotético',s.taxi]].map(([label,cost])=>`<div class="comparison-row"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${cost/max*100}%"></div></div><b>${money(cost,0)}</b></div>`).join('')}<p class="dim" style="font-size:9px;margin-top:14px">Comparação de custo operacional alocado. A aquisição não entra nestes cenários. Valores fictícios; abra as premissas abaixo.</p><div class="mini-actions"><button class="mini-button" data-action="download-sim">Baixar resumo da simulação ↓</button><button class="mini-button" data-action="sim-to-booking">Experimentar agendamento <span class="arrow-ne" aria-hidden="true"></span></button></div></div>`;
 }catch(e){$('#sim-error').hidden=false;$('#sim-error').textContent=e.message;$('#sim-result').innerHTML='<div class="sim-result"><h4>Vamos ajustar sua simulação.</h4><p>Corrija os campos indicados para ver os resultados.</p></div>';$('#comparison').innerHTML='';}}
function visibleOwner(){return cotista==='todos'?null:Number(cotista);}
function financialStats(f){const i=visibleOwner(),s=i===null?null:f.saldos[i];return {total:s?s.devido/100:f.total/100,horas:s?s.horas:f.horas,pago:s?s.pago/100:f.total/100,saldo:s?s.saldo/100:0};}
function renderFinanceiro(){const f=financeiro(mesFinanceiro),s=financialStats(f),i=visibleOwner();
 content.innerHTML=heading('Cada número tem uma história.','Fechamentos de 2026 · valores e participantes inteiramente fictícios.')+`
 <div class="filter-row"><div class="filter-controls"><label class="field">Competência<select id="finance-month">${MESES.map((m,j)=>`<option value="${j}" ${j===mesFinanceiro?'selected':''}>${m} de 2026</option>`).join('')}</select></label><label class="field">Visualização<select id="finance-owner"><option value="todos" ${cotista==='todos'?'selected':''}>Toda a aeronave</option>${COTISTAS.map((nome,j)=>`<option value="${j}" ${String(j)===cotista?'selected':''}>${nome}</option>`).join('')}</select></label></div></div>
 <div class="stat-grid">${stat(i===null?'DESPESAS DA AERONAVE':'SUA PARTE NAS DESPESAS',money(s.total),MESES[mesFinanceiro]+' · inclui reserva de manutenção')}${stat(i===null?'TEMPO DE VOO TOTAL':'SEU TEMPO DE VOO',formatarHoras(s.horas),i===null?'Soma dos três cotistas':COTISTAS[i])}${stat('CUSTO EFETIVO POR HORA',money(s.total/s.horas,0),'Despesas + reserva ÷ horas do período','gold')}</div>
 <div class="portal-two"><div class="panel"><div class="chart-title-row"><h4>Evolução de ${i===null?'toda a aeronave':COTISTAS[i]}</h4><div class="chart-toggle"><button data-action="chart" data-value="custos" aria-pressed="${chartMetric==='custos'}">Custos</button><button data-action="chart" data-value="horas" aria-pressed="${chartMetric==='horas'}">Horas</button></div></div>${barChart()}</div><div class="panel"><h4>Centro de custo · ${MESES[mesFinanceiro]}</h4>${donutChart(f)}</div></div>
 <div class="financial-tabs" role="group" aria-label="Relatório financeiro"><button data-action="finance-view" data-value="balanco" aria-pressed="${financeView==='balanco'}">Balanço entre cotistas</button><button data-action="finance-view" data-value="lancamentos" aria-pressed="${financeView==='lancamentos'}">Lançamentos e rateios</button><button data-action="finance-view" data-value="viagem" aria-pressed="${financeView==='viagem'}">Despesas de viagem</button></div><div id="finance-detail">${financeView==='balanco'?balanceTable(f):financeView==='lancamentos'?ledgerTable(f):travelReport(f)}</div>
 <div class="demo-hint">Os fixos são divididos em três partes iguais; os variáveis seguem as horas de uso do mês (40%, 35% e 25%). Cada centavo é conciliado. Este histórico é independente do simulador e dos voos que você criar na demo.</div>`;
}
function barChart(){const data=MESES.map((_,m)=>{const f=financeiro(m),s=financialStats(f);return chartMetric==='custos'?s.total:s.horas;}),max=Math.max(...data);
 return `<div class="chart-bars" role="group" aria-label="${chartMetric==='custos'?'Despesas em reais':'Horas voadas'} de junho a novembro de 2026">${data.map((v,j)=>`<button class="chart-column ${j===mesFinanceiro?'selected':''}" data-action="select-finance-month" data-month="${j}" aria-label="${MESES[j]}: ${chartMetric==='custos'?money(v,0):formatarHoras(v)}" aria-pressed="${j===mesFinanceiro}"><span class="bar-value">${chartMetric==='custos'?num(v/1000,1)+' mil':num(v,1)+' h'}</span><span class="chart-bar" style="height:${v/max*100}px"></span><span class="bar-month">${MESES[j].slice(0,3)}</span></button>`).join('')}</div>`;
}
function donutChart(f){const i=visibleOwner(),categories=['FIXO','VARIÁVEL'],costs=categories.map(c=>f.lancamentos.filter(l=>l.regra===c&&l.categoria!=='RESERVA').reduce((s,l)=>s+(i===null?l.valorCentavos:l.partes[i]),0)),reserve=f.lancamentos.filter(l=>l.categoria==='RESERVA').reduce((s,l)=>s+(i===null?l.valorCentavos:l.partes[i]),0);costs.push(reserve);const total=costs.reduce((a,b)=>a+b,0),a=costs[0]/total*100,b=a+costs[1]/total*100;
 return `<div class="cost-donut-layout"><div class="donut" style="background:conic-gradient(#d8b976 0% ${a}%,#739db4 ${a}% ${b}%,#87b59e ${b}% 100%)" role="img" aria-label="${['Fixos','Variáveis','Reserva'].map((label,j)=>`${label}: ${num(costs[j]/total*100,1)}%`).join('; ')}"><span><strong>100%</strong>distribuído</span></div><div class="donut-legend">${['Fixos','Variáveis','Reserva'].map((label,j)=>`<div><span><i style="background:${['#d8b976','#739db4','#87b59e'][j]}"></i>${label}</span><b>${num(costs[j]/total*100,1)}%</b></div>`).join('')}</div></div><p class="dim" style="font-size:9px">Veja cada despesa na aba de lançamentos.</p>`;
}
function balanceTable(f){const owner=visibleOwner(),shown=f.saldos.filter((_,j)=>owner===null||j===owner);
 return `<p class="dim">Quem antecipou despesas e como o rateio fecha. Saldo positivo representa crédito a receber no acerto.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>COTISTA</th><th class="num">PARTE NO RATEIO</th><th class="num">PAGOU DIRETAMENTE</th><th class="num">SALDO NO ACERTO</th></tr></thead><tbody>${shown.map(s=>`<tr><td>${s.nome}<br><span class="dim" style="font-size:8px">1/3 dos fixos · ${num(s.horas/f.horas*100)}% do uso</span></td><td class="num">${money(s.devido/100)}</td><td class="num">${money(s.pago/100)}</td><td class="num ${s.saldo>=0?'positive':'negative'}">${money(Math.abs(s.saldo)/100)}<br><span style="font-size:8px">${s.saldo>=0?'A RECEBER':'A COMPENSAR'}</span></td></tr>`).join('')}</tbody><tfoot><tr><td>${owner===null?'TOTAL CONCILIADO':'TOTAL SELECIONADO'}</td><td class="num">${money(shown.reduce((s,x)=>s+x.devido,0)/100)}</td><td class="num">${money(shown.reduce((s,x)=>s+x.pago,0)/100)}</td><td class="num">${money(shown.reduce((s,x)=>s+x.saldo,0)/100)}</td></tr></tfoot></table></div><p class="dim" style="font-size:9px;margin-top:12px">As antecipações são fictícias. O acerto compensa quem pagou acima da própria participação; não representa uma cobrança real.</p>`;
}
function filteredLedger(f){return f.lancamentos.filter(l=>categoria==='TODAS'||l.categoria===categoria);}
function ledgerTable(f){const rows=filteredLedger(f),i=visibleOwner();return `<div class="filter-controls"><label class="field">Categoria dos lançamentos<select id="finance-category"><option value="TODAS">Todas as categorias</option>${[...new Set(f.lancamentos.map(l=>l.categoria))].map(c=>`<option ${c===categoria?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>DESPESA / COMPROVANTE</th><th>CRITÉRIO</th><th class="num">VALOR TOTAL</th>${COTISTAS.map((c,j)=>i===null||i===j?`<th class="num">${j===0?'PILOT DA SHARE':c.toUpperCase()}</th>`:'').join('')}<th>PAGO POR</th></tr></thead><tbody>${rows.map(l=>`<tr><td><button class="doc-link" data-action="proof" data-id="${l.id}">${l.descricao} <span class="arrow-ne" aria-hidden="true"></span></button><br><span class="dim" style="font-size:8px">${String(l.dia).padStart(2,'0')}/${String(mesFinanceiro+6).padStart(2,'0')} · ${l.categoria}</span></td><td>${l.regra==='FIXO'?'PARTICIPAÇÃO':'HORAS VOADAS'}</td><td class="num">${money(l.valorCentavos/100)}</td>${l.partes.map((p,j)=>i===null||i===j?`<td class="num">${money(p/100)}</td>`:'').join('')}<td>${COTISTAS[l.pagoPor]}</td></tr>`).join('')}</tbody><tfoot><tr><td>SUBTOTAL DO FILTRO</td><td></td><td class="num">${money(rows.reduce((s,l)=>s+l.valorCentavos,0)/100)}</td>${COTISTAS.map((_,j)=>i===null||i===j?`<td class="num">${money(rows.reduce((s,l)=>s+l.partes[j],0)/100)}</td>`:'').join('')}<td></td></tr></tfoot></table></div><p class="dim" style="font-size:9px;margin-top:12px">O filtro de categoria afeta os lançamentos. Os indicadores e gráficos acima continuam mostrando a competência completa.</p>`;}
// Cada voo tem seu próprio relatório, com os itens em ordem de data.
// Os totais conciliam com a linha de viagem do fechamento, inclusive os centavos.
function travelReports(f){
 const l=f.lancamentos.find(l=>l.categoria==='VIAGEM');
 const mes=String(f.mes+6).padStart(2,'0');
 const destinos=['Sinop','Rondonópolis','Goiânia'];
 return l.partes.map((total,j)=>{
  const numero=String(f.mes*3+j+1).padStart(4,'0'),voo=`DEMO-${numero}/26`,id=`REL-${voo}`;
  const dia=3+j*10,data=d=>`${String(d).padStart(2,'0')}/${mes}/${f.ano}`;
  const valores=ratearCentavos(total,[85,150,45,85,150,45]);
  const despesas=[
   ['Alimentação','Almoço da tripulação',0],
   ['Hospedagem','Hospedagem da tripulação · primeira diária',0],
   ['Transporte','Transfer do aeroporto ao hotel',0],
   ['Alimentação','Jantar da tripulação',1],
   ['Hospedagem','Hospedagem da tripulação · segunda diária',1],
   ['Transporte','Transfer do hotel ao aeroporto',2],
  ];
  return {id,voo,cliente:COTISTAS[j],cotista:j,aeronave:DEMO_AIRCRAFT_LABEL,tripulante:'Piloto demonstrativo',
   trecho:`Cuiabá → ${destinos[j]} → Cuiabá`,inicio:data(dia),fim:data(dia+2),total,
   itens:despesas.map(([categoria,descricao,offset],k)=>({id:`${id}-${k+1}`,categoria,descricao,data:data(dia+offset),valor:valores[k],pagoPor:COTISTAS[l.pagoPor]}))};
 });
}
function travelReport(f){
 const i=visibleOwner(),relatorios=travelReports(f).filter(r=>i===null||r.cotista===i);
 return `<section class="travel-reports" aria-label="Relatórios de despesa por voo">
 <div class="panel-title"><div><h4>Relatórios de Despesa de Viagem</h4><p class="dim">Um relatório por voo, com todas as despesas e seus comprovantes.</p></div><span class="badge">${relatorios.length} ${relatorios.length===1?'VOO':'VOOS'}</span></div>
 ${relatorios.map((r,j)=>`<details class="panel travel-report" ${j===0?'open':''}>
  <summary class="travel-report-summary"><span><strong>Voo ${r.voo}</strong><small>${r.trecho} · ${r.inicio} a ${r.fim}</small></span><span class="travel-report-amount"><strong>${money(r.total/100)}</strong><small>Ver relatório <span aria-hidden="true">⌄</span></small></span></summary>
  <div class="travel-report-body"><div class="panel-title"><div><h4>Relatório de Despesa de Viagem</h4><p class="dim">${r.id}</p></div><span class="badge success">APROVADO · DEMO</span></div>
  <dl class="travel-report-info"><div><dt>Cliente</dt><dd>${r.cliente}</dd></div><div><dt>Aeronave</dt><dd>${r.aeronave}</dd></div><div><dt>Voo</dt><dd>${r.voo}</dd></div><div><dt>Período</dt><dd>${r.inicio} a ${r.fim} (3 dias)</dd></div><div><dt>Tripulante 1</dt><dd>${r.tripulante}</dd></div><div><dt>Trecho</dt><dd>${r.trecho}</dd></div></dl>
  <h4>Relação das despesas</h4><div class="table-wrap"><table class="data-table"><caption class="sr-only">Despesas do voo ${r.voo}</caption><thead><tr><th>DATA</th><th>DESCRIÇÃO</th><th>CATEGORIA</th><th class="num">VALOR</th><th>PAGO POR</th><th>COMPROVANTE</th></tr></thead><tbody>${r.itens.map(x=>`<tr><td>${x.data}</td><td>${x.descricao}</td><td>${x.categoria}</td><td class="num">${money(x.valor/100)}</td><td>${x.pagoPor}</td><td><button class="doc-link" data-action="travel-proof" data-report="${r.id}" data-id="${x.id}">Abrir exemplo <span class="arrow-ne" aria-hidden="true"></span></button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="3">TOTAL DAS DESPESAS DO VOO</td><td class="num">${money(r.total/100)}</td><td colspan="2"></td></tr></tfoot></table></div>
  <div class="travel-report-total"><span>Total pago por ${r.itens[0].pagoPor}</span><strong>${money(r.total/100)}</strong></div>
  </div></details>`).join('')}
 <p class="dim travel-report-note">Total dos relatórios ${i===null?'da aeronave':`de ${COTISTAS[i]}`} em ${MESES[f.mes]}: <strong>${money(relatorios.reduce((s,r)=>s+r.total,0)/100)}</strong>. Os valores já compõem a linha “Despesas de viagem” do fechamento e não são somados novamente. Voos, despesas e comprovantes são demonstrativos.</p></section>`;
}
function travelProof(relatorio,item){
 modal(`<h3 id="dialog-title">Comprovante anexado · exemplo</h3><p>Despesa vinculada ao voo ${relatorio.voo}. Documento demonstrativo, sem validade fiscal.</p><div class="receipt"><p class="watermark">EXEMPLO · SEM VALIDADE FISCAL</p>${[
  ['Relatório',relatorio.id],['Voo',relatorio.voo],['Cliente',relatorio.cliente],['Trecho',relatorio.trecho],['Descrição',item.descricao],['Categoria',item.categoria],['Data',item.data],['Pago por',item.pagoPor],['Valor',money(item.valor/100)],
 ].map(([label,value])=>`<div class="receipt-row"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><p>Na operação real, o comprovante de cada item acompanha o relatório deste voo.</p>`);
}

function renderManutencao(){content.innerHTML=heading('Uma operação que olha adiante.','Acompanhe horas disponíveis, vencimentos e documentos.','CENÁRIO FICTÍCIO')+`<div class="stat-grid">${stat('INSPEÇÃO PROGRAMADA','42 <small>horas</small>','Disponíveis no cenário demonstrativo')}${stat('DOCUMENTOS NO PAINEL','3 <small>itens</small>','Exemplos ilustrativos, sem validade legal')}${stat('AERONAVE DEMONSTRATIVA','DEMO-01','Turboélice executivo · referência fictícia','gold')}</div><section class="panel"><div class="panel-title"><h4>Radar de manutenção</h4><span class="badge">CONTROLE POR HORAS E DATAS</span></div>${[['Inspeção periódica','Controle por horas','42 h restantes',42, 'PLANEJADA'],['Reserva para revisão de motores','Planejamento de longo prazo','640 h restantes',70,'EM ACOMPANHAMENTO'],['Revisão documental','Controle por calendário','18 dias restantes',25,'ATENÇÃO']].map(([nome,tipo,valor,percent,status])=>`<div class="maintenance-row"><div><strong>${nome}</strong><p>${tipo}</p></div><div><p>${valor}</p><div class="meter" aria-hidden="true"><i style="width:${percent}%;background:${status==='ATENÇÃO'?'#d8b976':'#81aa96'}"></i></div></div><span class="badge ${status==='ATENÇÃO'?'warning':'success'}">${status}</span></div>`).join('')}</section><section class="panel" style="margin-top:16px"><h4 style="margin-bottom:15px">Documentos e diário de bordo</h4><div class="document-list">${[['seguro','Seguro aeronáutico','Exemplo de acompanhamento documental'],['documentos','Controle de documentos','Validades e organização da aeronave'],['diario','Diário de bordo digital','Exemplo de etapas e horários registrados']].map(([id,nome,copy])=>`<button class="document-item" data-action="document" data-id="${id}"><span>${nome}<small>${copy}</small></span><span aria-hidden="true"><span class="arrow-ne" aria-hidden="true"></span></span></button>`).join('')}</div></section><div class="demo-hint">O painel exemplifica o acompanhamento de manutenção e documentação. Não atesta aeronavegabilidade nem substitui a avaliação técnica e os registros oficiais da aeronave.</div>`;}
