function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadSim(){try{const s=simular(simDraft),p=PREMISSAS;download('share-brasil-simulacao-demonstrativa.txt',`SHARE BRASIL — SIMULAÇÃO DIDÁTICA\nDADOS FICTÍCIOS. NÃO É PROPOSTA COMERCIAL.\n\nRota: ${s.origem} → ${s.destino}${s.idaVolta?' → '+s.origem:''}\nDistância aproximada: ${num(s.km)} km\nTempo: ${formatarHoras(s.horas)}\nJornada: ${s.dias} dia(s) / ${s.passageiros} passageiro(s)\nCotas: ${s.cotas}; seu uso anual: ${s.horasAno} horas\n\nCurto prazo: ${money(s.curto)}\n - Combustível: ${money(s.combustivel)}\n - Hotel: ${money(s.hotel)}\n - Diárias: ${money(s.diarias)}\n - Taxas: ${money(s.taxas)}\n - Hangar fora da base: ${money(s.hangar)}\nMédio prazo: ${money(s.medio)}\nLongo prazo: ${money(s.longo)}\nTOTAL ALOCADO: ${money(s.total)}\nPor hora: ${money(s.custoHora)}\nPor passageiro: ${money(s.porAssento)}\nSua parcela fixa mensal: ${money(s.fixoMes)}\n\nMesma viagem em propriedade integral: ${money(s.privada)}\nTáxi aéreo hipotético: ${money(s.taxi)}\n\nPREMISSAS DIDÁTICAS\n${p.velocidadeKmh} km/h + 9 min/trecho; ${p.litrosHora} L/h a ${money(p.combustivelLitro)}/L. Fixos anuais: ${money(p.fixoAnual)} / cotas / horas por cotista. Reserva: ${money(p.reservaHora)}/h. Dois tripulantes, diária ${money(p.diariaPessoa)}/pessoa/dia, hotel ${money(p.hotelPessoa)}/pessoa/noite, hangar ${money(p.hangarNoite)}/noite, taxa ${money(p.taxaTrecho)}/trecho. Noites = dias − 1. Táxi hipotético: ${money(p.taxiHora)}/h + taxas e estadia.\n\nNão inclui aquisição, financiamento, depreciação, tributos específicos, reposicionamentos ou custos extraordinários. Rotas em linha reta. Não é planejamento operacional, cotação, oferta de transporte ou promessa de economia.\n\nConverse com a Share: (65) 98173-0641 / (65) 98146-7766\nhttps://conheca.share-brasil.com/\n`);toast('Resumo da simulação preparado.');}catch(e){toast(e.message);}}
function showDocument(id){if(id==='diario'){modal(`<h3 id="dialog-title">Diário de bordo · exemplo</h3><p>Registro fictício de uma viagem. Horários locais ilustrativos; não constituem um diário oficial.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>ETAPA</th><th>AC</th><th>DEP</th><th>POU</th><th>COR</th></tr></thead><tbody><tr><td>SBCY → SBSI</td><td>09:00</td><td>09:10</td><td>10:20</td><td>10:25</td></tr><tr><td>SBSI → SBCY</td><td>16:00</td><td>16:10</td><td>17:20</td><td>17:25</td></tr></tbody></table></div><p style="margin-top:17px">Tempo de voo: 2h20min · tempo total entre acionamento e corte: 2h50min. Tripulação e passageiros registrados na operação real.</p>`);}else{modal(`<h3 id="dialog-title">${id==='seguro'?'Seguro aeronáutico':'Organização documental'}</h3><div class="receipt"><p class="watermark">EXEMPLO · SEM VALIDADE LEGAL</p><p>${id==='seguro'?'O portal permite acompanhar a organização e a validade dos documentos de seguro da aeronave. Este exemplo não é uma apólice e não comprova cobertura.':'Documentos ficam organizados para consulta e acompanhamento de validades. Este exemplo representa a experiência de navegação, sem reproduzir certificados ou documentos reais.'}</p></div><p>Aeronave de referência: DEMO-01. Todos os dados desta apresentação são fictícios.</p>`);}}
function action(e){const b=e.target.closest('[data-open],[data-date],[data-action]');if(!b||b.disabled)return;
 if(b.dataset.open){goTab(b.dataset.open,true);return;}
 if(b.dataset.date){draft.data=b.dataset.date;$('#booking-form [name=data]').value=draft.data;renderCalendar();updateBookingSummary();return;}
 switch(b.dataset.action){
  case 'booking-view':bookingView(b.dataset.value);break;
  case 'swap-airports':{captureBooking($('#booking-form'));const origin=draft.origem;draft.origem=draft.destino;draft.destino=origin;renderAgenda();break;}
  case 'month':month.setMonth(month.getMonth()+Number(b.dataset.dir));renderCalendar();break;
  case 'confirm-booking':{const v=reservas.find(v=>v.id===b.dataset.id);if(v?.status==='SOLICITADO'){v.status='CONFIRMADO';persist();renderAgenda();toast('Confirmação simulada: número do voo e tripulação disponíveis. Nenhum e-mail foi enviado.');}break;}
  case 'cancel-booking':{const v=reservas.find(v=>v.id===b.dataset.id);if(v)modal(`<h3 id="dialog-title">Cancelar esta reserva?</h3><p>${v.origem} → ${v.destino} · ${fmtDate(v.data)} · ${v.horario}. A data ficará disponível novamente na demonstração.</p><div class="mini-actions"><button class="mini-button danger" data-action="do-cancel" data-id="${v.id}">Sim, cancelar reserva</button><button class="mini-button" data-action="close">Manter reserva</button></div>`);break;}
  case 'do-cancel':{const v=reservas.find(v=>v.id===b.dataset.id);if(v){v.status='CANCELADO';persist();dialog.close();renderAgenda();toast('Reserva demonstrativa cancelada.');}break;}
  case 'close':dialog.close();break;
  case 'reset':reservas=reservasIniciais();persist();simDraft={origem:'SBCY',destino:'SBSI',horasAno:120,cotas:3,dias:1,passageiros:4,idaVolta:true};mesFinanceiro=5;cotista='todos';categoria='TODAS';financeView='balanco';chartMetric='custos';unit='km';fact=0;month=new Date();month.setDate(1);month.setHours(12,0,0,0);let day=deslocarData(hojeISO(),1);while(dataBloqueada(day,reservas))day=deslocarData(day,1);draft={origem:'SBCY',destino:'SBSI',data:day,horario:'09:00',passageiros:4,emprestado:false};dialog.close();goTab('resumo');toast('A experiência voltou ao cenário inicial.');break;
  case 'unit':unit=b.dataset.value;renderResumo();break;
  case 'fact':fact++;renderResumo();break;
  case 'chart':chartMetric=b.dataset.value;renderFinanceiro();break;
  case 'select-finance-month':mesFinanceiro=Number(b.dataset.month);renderFinanceiro();break;
  case 'finance-view':financeView=b.dataset.value;renderFinanceiro();break;
  case 'proof':{const l=financeiro(mesFinanceiro).lancamentos.find(l=>l.id===b.dataset.id);if(l)proof(l);break;}
  case 'travel-proof':{const r=travelReports(financeiro(mesFinanceiro)).find(r=>r.id===b.dataset.report),x=r?.itens.find(x=>x.id===b.dataset.id);if(x)travelProof(r,x);break;}
  case 'download-sim':downloadSim();break;
  case 'sim-to-booking':draft={...draft,origem:simDraft.origem,destino:simDraft.destino,passageiros:Number(simDraft.passageiros)};goTab('agenda',true);toast('Rota e passageiros copiados. Escolha uma data para testar o agendamento.');break;
  case 'document':showDocument(b.dataset.id);break;
 }
}
content.addEventListener('click',action);$('#dialog-content').addEventListener('click',action);
$('#interest-choices').addEventListener('change',e=>{const text=`Olá! Conheci a apresentação da Share Brasil e quero conversar sobre ${e.target.value}.`;$('#whatsapp-primary').href=`https://wa.me/5565981730641?text=${encodeURIComponent(text)}`;});
$('#current-year').textContent=new Date().getFullYear();
function progress(){const total=document.documentElement.scrollHeight-window.innerHeight;$('#reading-progress').style.width=`${total>0?window.scrollY/total*100:0}%`;}
window.addEventListener('scroll',progress,{passive:true});window.addEventListener('resize',progress);progress();
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('.chapter-bar nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${e.target.id}`));}},{rootMargin:'-20% 0px -60% 0px'});document.querySelectorAll('.chapter').forEach(s=>observer.observe(s));
const requestedDemo=new URLSearchParams(window.location.search).get('demo');
if(['resumo','agenda','simulador','financeiro','manutencao'].includes(requestedDemo))goTab(requestedDemo);else render();
// A versão de impressão reúne todas as frentes e as telas demonstrativas.
const printServices=document.createElement('div');printServices.className='print-services';printServices.innerHTML=services.map((_,i)=>`<article>${serviceMarkup(i)}</article>`).join('');$('.services').after(printServices);
let printNode=null,printOpen=[];
window.addEventListener('beforeprint',()=>{
 printOpen=[...document.querySelectorAll('.faq-list details')].map(d=>d.open);document.querySelectorAll('.faq-list details').forEach(d=>d.open=true);
 const original=tab;
 const snapshots=[];
 for(const [view,label] of [['resumo','Visão geral do cotista'],['agenda','Solicitação e agenda'],['simulador','Simulação de custos'],['financeiro','Transparência financeira'],['manutencao','Manutenção e documentos']]){
  tab=view;render();const clone=content.cloneNode(true);if(view==='financeiro')clone.querySelector('#finance-detail').innerHTML=`<h4>Balanço do mês</h4>${balanceTable(financeiro(mesFinanceiro))}<h4 style="margin-top:20px">Lançamentos e rateios</h4>${ledgerTable(financeiro(mesFinanceiro))}<h4 style="margin-top:20px">Despesas de viagem</h4>${travelReport(financeiro(mesFinanceiro))}`;clone.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));clone.removeAttribute('id');clone.querySelectorAll('details').forEach(d=>d.open=true);
  snapshots.push(`<article><h3>${label}</h3>${clone.innerHTML}</article>`);
 }
 tab=original;render();printNode?.remove();printNode=document.createElement('div');printNode.className='print-demo';printNode.innerHTML=snapshots.join('');$('.demo-shell').after(printNode);
});
window.addEventListener('afterprint',()=>{printNode?.remove();printNode=null;document.querySelectorAll('.faq-list details').forEach((d,i)=>d.open=printOpen[i]||false);});

// Reveal groups once as they enter the page, without hiding content if scripts fail.
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
 const reveals=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;el.classList.remove('scroll-pending');el.classList.add('scroll-visible');reveals.unobserve(el);});},{threshold:0});
 document.querySelectorAll('.section-head,.intro-grid,.foundation>div,.split-heading,.ownership-layout,.services,.safety-row,.experience-benefits>div,.faq-list,.contact-grid').forEach(el=>{if(el.getBoundingClientRect().top>window.innerHeight){el.classList.add('scroll-pending');reveals.observe(el);}});
 animateScreen($('.hero-content'));
}

